    int head_ = 0;   // index of first element
    int count_ = 0;

    RingBuffer(int capacity) : cap_(capacity) {}

    bool push(int value) {
        if (full()) return false;
        data_[(head_ + count_) % cap_] = value;
        ++count_;
        return true;
    }

    bool pop(int& out) {
        if (empty()) return false;
        out = data_[head_];
        head_ = (head_ + 1) % cap_;
        --count_;
        return true;
    }

    int size() const { return count_; }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == cap_; }

private:
    int cap_;
};

