double mlp_loss_and_grad(const double* params, int n_in, int n_hidden,
                         const double* X, const double* y, int n_samples,
                         double* grad) {
    const int nW1 = n_hidden * n_in;
    const int nb1 = nW1 + n_hidden;
    const int nW2 = nb1 + n_hidden;
    const double* W1 = params;
    const double* b1 = params + nW1;
    const double* W2 = params + nb1;
    const double b2 = params[nW2];

    for (int i = 0; i < nW2 + 1; ++i) grad[i] = 0.0;

    double loss = 0.0;
    for (int s = 0; s < n_samples; ++s) {
        const double* x = X + s * n_in;
        for (int j = 0; j < n_hidden; ++j) {
            double a = b1[j];
            for (int k = 0; k < n_in; ++k) a += W1[j * n_in + k] * x[k];
            const double h = std::tanh(a);
            const double z = W2[j] * h + b2;
            const double p = 1.0 / (1.0 + std::exp(-z));
            const double yy = y[s];
            loss += -(yy * std::log(p) + (1.0 - yy) * std::log(1.0 - p));
            const double dz = (p - yy) / n_samples;
            grad[nW2] += dz;
            grad[nb1 + j] += dz * h;
            const double dh = dz * W2[j] * (1.0 - h * h);
            grad[nW1 + j] += dh;
            for (int k = 0; k < n_in; ++k) grad[j * n_in + k] += dh * x[k];
        }
    }
    return loss / n_samples;
}
